  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Una observación _______ en la inspección técnica vehicular, es aquella de carácter documentario y/o técnico que no exige una nueva inspección técnica vehicular, debiendo subsanarse las observaciones efectuadas antes de la siguiente Inspección Técnica Vehicular.', 'single', 'Fundamento: Articulo 19 del Reglamento Nacional de Inspecciones Técnicas Vehiculares.', 118, null) returning id into v_q;
