  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Una observación ______ en la inspección técnica vehicular, es aquella que ocasiona la desaprobación de la Inspección Técnica Vehicular, exigiendo su subsanación mediante una re- inspección sobre las deficiencias consignadas dentro del plazo máximo de 30 días.', 'single', 'Fundamento: Articulo 20 del Reglamento Nacional de Inspecciones Técnicas Vehiculares.', 119, null) returning id into v_q;
