  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Una observación ______, en la inspección técnica vehicular, es aquella que ocasionan la desaprobación de la Inspección Técnica Vehicular, debiéndose trasladar el vehículo al taller de mantenimiento mecánico, que determine el propietario o conductor, para la subsanación de la misma.', 'single', 'Fundamento: Articulo 21 del Reglamento Nacional de Inspecciones Técnicas Vehiculares.', 120, null) returning id into v_q;
