  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Por cuantos caracteres esta constituido el Número de Identificación Vehicular?', 'single', 'Fundamento: El VIN esta constituido por 17 caracteres, según el artículo 12 del RNV.', 122, null) returning id into v_q;
