  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'El Reglamento Nacional de Vehículos, señala que el parachoques delantero y posterior:', 'single', 'Fundamento: Artículo 14 del RNV señala que 7. Parachoques delantero sin filos angulares cortantes, ni que excedan el ancho del vehículo. 8. Parachoques posterior y/o dispositivo antiempotramiento sin filos angulares cortantes, ni que excedan el ancho del vehículo. Tratándose de dispositivo antiempotramiento se debe cumplir con los requisitos técnicos aprobados.', 123, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Puede contar con filos angulares cortantes', false, 0), (v_q, 'No debe exceder el ancho del vehículo', true, 1), (v_q, 'Puede o no exceder el ancho del vehículo', false, 2), (v_q, 'Puede exceder el ancho del vehículo pero sin filos angulares cortantes', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué definición corresponde a luz alta en el Reglamento Nacional de Vehículos?', 'single', 'Fundamento: Anexo II del RNV.', 124, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Luz utilizada para alumbrar una mayor distancia de la vía por delante del vehículo, también denominada de carretera.', true, 0), (v_q, 'Luz utilizada para alumbrar una mayor distancia de la vía, también denominada luz complementaria.', false, 1), (v_q, 'Haz de luz abierto y de corto alcance ubicado en la parte delantera del vehículo para alumbrar la carretera en condiciones de neblina.', false, 2), (v_q, 'Ninguna de las anteriores', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'El Reglamento Nacional de Vehículos define a los frenos como:', 'single', 'Fundamento: Anexo II del RNV.', 125, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Conjunto de elementos del vehículo que permite reducir la velocidad, detener o asegurar la parada del vehículo.', true, 0), (v_q, 'Conjunto de elementos del vehículo que permite reducir la velocidad para detener el vehículo, sin que ello signifique asegurar la parada del vehículo.', false, 1), (v_q, 'Conjunto de elementos del vehículo que sirve solo para detener completamente el vehículo.', false, 2), (v_q, 'Ninguna de las anteriores', false, 3);
