  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Los vehículos que circulan por las vías del SNTT, deben contar con carrocería diseñada para evitar salpicaduras de las ruedas y/o protegida por guardafangos', 'single', 'Fundamento: Artículo 12 del RNV: 5. Carrocería diseñada para evitar las salpicaduras de las ruedas y/o protegida por guardafangos o escarpines.', 128, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Si.', true, 0), (v_q, 'No.', false, 1), (v_q, 'Depende del tamaño del vehículo.', false, 2), (v_q, 'No se encuentra regulado si debe contar o no.', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Los vehículos podrán contar con accesorios (defensas especiales delanteras, barras antivuelco, parrillas de techo, alerones, spoilers, viseras, estribos, etc.) siempre y cuando estos tengan bordes ______.', 'single', 'Fundamento: Artículo 27 del RNV: Los vehículos podrán contar con accesorios tales como defensas especiales delanteras y posteriores, barras antivuelco, parrillas de techo, alerones, spoilers, viseras, estribos, soportes y cubiertas de rueda de repuesto, soportes de galoneras, enganche para remolque, bases de pértigas y antenas, winches, escaleras posteriores, soportes centrales de toldo, tomas de aire del motor laterales, entre otros, siempre y cuando éstos tengan bordes redondeados, es decir que no presenten elementos punzocortantes, aristas ni ángulos salientes que representen peligro para las personas y atenten contra la seguridad.', 129, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Redondeados y con ángulos salientes para su visibilidad', false, 0), (v_q, 'Redondeados y con ciertas aristas', false, 1), (v_q, 'Redondeados', true, 2), (v_q, 'Cuadrados o rectos, sin ángulos que sobre salgan del vehículo', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Los vehículos podrán contar con accesorios (defensas especiales delanteras, barras antivuelco, parrillas de techo, alerones, spoilers, viseras, estribos, etc.) siempre y cuando estos no excedan más de ______ de los extremos delantero y posterior del vehículo.', 'single', 'Fundamento: Artículo 27 del RNV.', 130, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, '250 mm.', false, 0), (v_q, '200 mm', true, 1), (v_q, '100 mm', false, 2), (v_q, '150 mm', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Sobre el limpiaparabrisas y lavaparabrisas es correcto:', 'single', 'Fundamento: Artículo 14 del RNV 4. Limpiaparabrisas y lavaparabrisas, que como mínimo, cubran el área frente al piloto y copiloto.', 131, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Como mínimo deben cubrir solo el área frente al piloto.', false, 0), (v_q, 'Como mínimo deben cubrir el área frente al piloto y copiloto.', true, 1), (v_q, 'El limpiaparabrisas debe cubrir el área del piloto y copiloto, y el lavabrisas solo el área frente al piloto.', false, 2), (v_q, 'No esta regulado en el área mínima, solo la exigibilidad de tener un solo limpiaparabrisas para el piloto.', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Cuales son las herramientas como mínimo que debe tener un vehículo para cambiar la rueda?, según el Reglamento Nacional de Vehículos', 'single', 'Fundamento: Artículo 14 del RNV 11. Rueda de repuesto y herramientas, como mínimo de acuerdo al siguiente detalle: 11.1 Una rueda de repuesto o de uso temporal, salvo que el vehículo cuente con un sistema alternativo al cambio de ruedas, que permita su movilidad hasta un taller de reparación. Tratándose de vehículos cuyos aros tengan diferentes diámetros, deben contar con una rueda de repuesto por cada diámetro de aro, salvo que el fabricante provea una sola rueda de repuesto compatible con las diferentes medidas de aro. 11.2. Herramientas para cambiar la rueda (gata completa que soporte al menos el 30% del peso bruto del vehículo y llave de ruedas), con excepción de aquellos vehículos que tengan sistemas alternativos como los indicados en el numeral 11.1.', 132, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Gata completa que soporte al menos el 30% del peso bruto del vehículo y llave de ruedas', true, 0), (v_q, 'Solo se exige la gata completa que soporte al menos el 40% del peso bruto del vehículo.', false, 1), (v_q, 'Gata completa que soporte el peso bruto del vehículo, llave de ruedas y seguro de las ruedas.', false, 2), (v_q, 'Set de llaves hexagonales y gata completa que soporte al menos el 30% del peso neto del vehículo.', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿A qué se consideran Vías Terrestres según el Reglamento Nacional de Vehículos?', 'single', 'Fundamento: Anexo II del RNV.', 133, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sistema de vías públicas incluyendo las concesionadas, así como las privadas, por donde circulan los vehículos, a excepción de las vías férreas.', true, 0), (v_q, 'Vía en que los vehículos y las personas sólo tienen oportunidad a ingresar o salir de ella, por los lugares y bajo las condiciones fijadas por la Autoridad competente', false, 1), (v_q, 'Sistema de vías públicas, incluyendo las vías férreas, sin considerar las concesionadas y las privadas.', false, 2), (v_q, 'Vía dentro del ámbito urbano, destinada a la circulación de vehículos y peatones y eventualmente de animales', false, 3);
