  insert into options (question_id, body, is_correct, "order") values (v_q, 'Llevar frecuentemente el vehículo al taller.', false, 0), (v_q, 'Que el conductor sepa realizar ciertas reparaciones del vehículo.', false, 1), (v_q, 'Realizar una inspección visual y controles básicos diarios', true, 2), (v_q, 'Llevar al taller del concesionario autorizado', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué indica la viscosidad de un aceite?', 'single', 'Fundamento: Es la capacidad de fluir sin mayor resistencia. En términos prácticos esto permite que se distribuya por todos los conductos diseñados para el paso del aceite.', 184, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La capacidad de pegarse sobre las superficies a lubricar.', false, 0), (v_q, 'La mayor o menor facilidad para pasar por las canalizaciones.', true, 1), (v_q, 'La capacidad de no descomponerse y permanecer inalterable con el tiempo.', false, 2), (v_q, 'Su capacidad higroscópica', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué es un cuenta revoluciones en el panel de instrumentos?', 'single', 'Fundamento: Es el llamado tacómetro que calcula el número de vueltas del cigüeñal o volante del motor. Se suele usar revoluciones por minuto.', 185, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Un indicador del número de vueltas que da el motor por una unidad de tiempo', true, 0), (v_q, 'Un indicador del número de vueltas que da el neumático por una unidad de tiempo', false, 1), (v_q, 'Un indicador del número de vueltas que da el diferencial por una unidad de tiempo', false, 2), (v_q, 'Un indicador del número de vueltas que da la caja de cambios por una unidad de tiempo', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Cómo se deben ajustar las tuercas de las ruedas?', 'single', 'Fundamento: El ajuste cruzado garantiza que las tuercas hagan el contacto correcto en un sentido para luego pasar al otro sentido. Al hacerlo en forma circular se produce un desnivel que fuerza el apriete final.', 186, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'No tiene orden', false, 0), (v_q, 'De forma cruzada', true, 1), (v_q, 'En secuencia', false, 2), (v_q, 'De atrás hacia delante', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Con el vehículo en funcionamiento, que indica la luz roja en forma de batería', 'single', 'Fundamento: Esa luz roja con forma de bateria es el testigo que algo anda mal con el sistema de carga, puede ser un defecto del alternador o conexiones o simplemente la batería ya deja de cargar adecuadamente. Si la batería está descargada no debe ni encender ninguna luz testigo.', 187, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Que la batería esta descargada', false, 0), (v_q, 'El alternador dejo de funcionar', true, 1), (v_q, 'Que la batería esta desconectada', false, 2), (v_q, 'Que la batería se encuentra con mucha carga', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'El refrigerante circula a través del motor impulsado por:', 'single', 'Fundamento: El refrigerante circula por medio de una bomba hidráulica. El vehículo tiene muchas bombas, en este caso se suele llamar bomba de agua.', 188, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Bomba de agua', true, 0), (v_q, 'Presión de aire', false, 1), (v_q, 'Pistón de vacío', false, 2), (v_q, 'Bomba de alimentación', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué entiende por panel de instrumentos?', 'single', 'Fundamento: Tambien es llamado tablero de instrumentos o consola y contienen muchos indicadores luminosos que advierten el estado de los sistemas del vehículo.', 189, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Señales de control en el tablero.', false, 0), (v_q, 'Indicadores luminosos al alcance de la vista.', false, 1), (v_q, 'Todas las anteriores.', true, 2), (v_q, 'Ninguna de las anteriores', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Los vehículos de categoría L deben contar con dispositivos para descansar los pies del conductor y de las personas transportadas?', 'single', 'Fundamento: Artículo 15.- Requisitos técnicos adicionales para los vehículos de la categoría L Adicionalmente, los vehículos de la categoría L deben contar con dispositivos para descansar los pies del conductor y de las personas transportadas.', 190, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Si', true, 0), (v_q, 'No', false, 1), (v_q, 'Depende de la carrocería del vehículo de categoría L', false, 2), (v_q, 'Solo deben contar con dispositivos para descansar los pies del conductor, no siendo obligatorio para las personas transportadas.', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿La Luz baja de un vehículo de categoría L debe ser de color?', 'single', 'Fundamento: El numeral 1 del Anexo III del RNV, señala que la luz alumbrado interior es color Blanco y en la Nota 11 indica que las luces interiores de los vehículos no deben ser de colores distintos al blanco y en ningún caso podrán ser intermitentes, centellantes o estroboscópicas.', 191, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Solo Blanco', false, 0), (v_q, 'Solo Amarillo', false, 1), (v_q, 'Cualquier color siempre que no sean centellantes', true, 2), (v_q, 'Blanco o Amarillo', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Según la clasificación vehicular, un vehículo automotor de tres ruedas se clasifica en la(s) categoría(s):', 'single', 'Fundamento: Anexo I del RNV.', 192, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'L1, L2 y L3.', false, 0), (v_q, 'L2, L4 y L5', true, 1), (v_q, 'L3 y L5', false, 2), (v_q, 'L2, L3 y L5', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿A qué distancia como mínimo debe ser audible el sonido de la bocina para los vehículos de categoría L?', 'single', 'Fundamento: Artículo 13 del RNV: 8. Bocina de sonido uniforme y continuo, audible como mínimo a una distancia de 50 metros para la categoría L y de 100 metros para la categorías M y N, cuya intensidad esté dentro de los Límites Máximos Permisibles que se establezcan. Únicamente se permite la instalación de sirenas en ambulancias, vehículos de bomberos, vehículos de rescate, vehículos policiales y vehículos celulares.', 193, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, '100 metros', false, 0), (v_q, '50 metros', true, 1), (v_q, '30 metros', false, 2), (v_q, 'No existe mínimo siempre que estén dentro de los límites máximos permisibles para emisiones sonoras', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué color esta permitido para la luz alta adicional en un vehículo de categoría L?', 'single', 'Fundamento: Anexo III del RNV.', 194, null) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Solo Blanco', false, 0), (v_q, 'Blanco o Amarillo', true, 1), (v_q, 'Blanco, Amarillo o Azul', false, 2), (v_q, 'Solo Amarillo', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'La licencia de conducir clase B categoría II C permite conducir vehículos señalados en la categoría', 'single', 'Fundamento: Artículo 12 del Reglamento de Licencias.', 195, null) returning id into v_q;
