-- =====================================================================
-- Memorepe — Crea 3 bancos de balotarios MTC (Perú): B-IIb motos, B-IIc mototaxis, A-IIa taxis
-- Correr COMPLETO una vez en el SQL Editor de Supabase. Si alguno ya existe, lo saltea.
-- =====================================================================

-- Balotario MTC B-IIb – Examen de reglas de tránsito para motos (Perú) (201 preguntas)
do $$
declare v_user uuid; v_quiz uuid; v_q uuid;
begin
  select id into v_user from users where username = 'memorepe';
  if v_user is null then raise exception 'No existe el usuario @memorepe'; end if;
  if exists (select 1 from quizzes where title = 'Balotario MTC B-IIb – Examen de reglas de tránsito para motos (Perú)') then raise notice 'Ya existe'; return; end if;
  values (v_user, 'Balotario MTC B-IIb – Examen de reglas de tránsito para motos (Perú)', 'Las preguntas del balotario oficial del MTC para el examen de reglas de tránsito de la licencia B-IIb (motocicletas) en Perú, con respuestas correctas y el fundamento legal de cada una.', 'otro', 'conducir', 'es', 'public', 'MTC Perú', 'Licencia de conducir B-IIb', 'balotario-mtc-b-iib-motos-peru') returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
end $$;

-- Balotario MTC B-IIc – Mototaxis: preguntas específicas (Perú) (30 preguntas)
do $$
