  if v_user is null then raise exception 'No existe el usuario @memorepe'; end if;
  if exists (select 1 from quizzes where title = 'Balotario MTC B-IIc – Mototaxis: preguntas específicas (Perú)') then raise notice 'Ya existe'; return; end if;
  values (v_user, 'Balotario MTC B-IIc – Mototaxis: preguntas específicas (Perú)', 'Las preguntas específicas del balotario oficial del MTC para la licencia B-IIc (mototaxis) en Perú, con respuestas y fundamento legal. Las preguntas generales son las mismas del balotario B-IIb.', 'otro', 'conducir', 'es', 'public', 'MTC Perú', 'Licencia de conducir B-IIc', 'balotario-mtc-b-iic-mototaxis-peru') returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
