  values (v_user, 'Balotario MTC A-IIa – Taxis: preguntas específicas (Perú)', 'Las preguntas específicas del balotario oficial del MTC para la licencia profesional A-IIa (taxis) en Perú, con respuestas y fundamento legal. Las preguntas generales son las mismas del balotario A-I.', 'otro', 'conducir', 'es', 'public', 'MTC Perú', 'Licencia de conducir A-IIa', 'balotario-mtc-a-iia-taxis-peru') returning id into v_quiz;
